type Metric; data Sample <: Metric { value::i64; }
function create(arena::region)::Sample { deref(alloc arena Sample(3)) }
export Metric; export Sample; export create;
function score(x::Metric)::i64 { 1 }
function hidden(x::Metric)::i64 { score(x) + score(x) }
function twice(x::Metric)::i64 { hidden(x) }
export score; export twice;

